{"file_path":"safety_evals/loader.py","content":""""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue

        parts = line.split(",")
        if len(parts) != 3:
            raise ValueError(f"line {line_number}: expected exactly 3 fields")

        id_text, day_text, flag_text = (part.strip() for part in parts)

        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: invalid flagged value")

        out.append({"id": id_text, "day": day, "flagged": flagged})
    return out



def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for event in events:
        seen[event["id"]] = event
    return sorted(seen.values(), key=lambda event: (event["day"], event["id"]))



def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts
