{"file_path":"tests/test_metrics.py","content":"from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups



def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5



def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3



def test_pooled_flag_rate_weights_by_transcript_count():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
    }
    assert pooled_flag_rate(groups) == 0.25



def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7



def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]



def test_parse_transcript_log_skips_blank_and_comment_lines_and_parses_empty_flag():
    lines = ["   ", "  # note", " x1 , 3 , "]
    assert parse_transcript_log(lines) == [{"id": "x1", "day": 3, "flagged": None}]



def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "a", "day": 2, "flagged": True},
        {"id": "x", "day": 1, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "x", "day": 1, "flagged": True},
        {"id": "a", "day": 2, "flagged": True},
    ]



def test_daily_flag_counts_uses_inclusive_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 4, "flagged": True},
        {"id": "d", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [0, 0, 1]



def test_monitor_summary_basic():
    groups = {
        "g1": [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}],
        "g2": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 1}



def test_top_flagged_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "c": [],
    }
    assert top_flagged_groups(groups, 3) == ["a", "b"]



def test_flag_rate_by_group_sorts_keys_and_uses_none_for_empty_group():
    groups = {"b": [{"flagged": True}], "a": []}
    assert flag_rate_by_group(groups) == {"a": None, "b": 1.0}



def test_longest_flag_streak_counts_consecutive_positive_entries():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, 0, 1]) == 3
